void calendar() {
  assert(validDate(20240229));
  assert(!validDate(20260229));
  assert(!validDate(20261301));
  assert(!validDate(20261100));
  for (unsigned year = 2024; year <= 2099; ++year) {
    for (unsigned month = 1; month <= 12; ++month) {
      for (unsigned day = 1; day <= monthDays(year, month); ++day) {
        const uint32_t date = year * 10000 + month * 100 + day;
        assert(epochDate(dateEpoch(date)) == date);
      }
    }
  }
  assert(mondayWeekday(20261109) == 0);
  assert(mondayWeekday(20261108) == 6);
}

void scheduling() {
  Config config = example();
  Alarm& alarm = config.alarms[0];
  alarm.weekdays = 1; alarm.wakeMinute = 10; alarm.rampMinutes = 30;
  Occurrence next = nextOccurrence(config, dateEpoch(20261108) + 23 * 3600, UTC);
  assert(next.date == 20261109);
  assert(next.start == dateEpoch(20261108) + 23 * 3600 + 40 * 60);
  assert(!nextOccurrence(config, next.start - 1, UTC, true));
  assert(nextOccurrence(config, next.start + 5, UTC, true));
  assert(waitForPresence(next, next.start + 5, Presence::Unknown, true));
  assert(!waitForPresence(next, next.start + PRESENCE_WAIT_SECONDS, Presence::Unknown, true));
  assert(waitForPresence(next, next.start + 120, Presence::Unknown, true, true)); // Boot during the rise.
  assert(!waitForPresence(next, next.wake + LATE_START_SECONDS + 1, Presence::Unknown, true, true));
  assert(!waitForPresence(next, next.start, Presence::Absent, true));
  assert(!waitForPresence(next, next.start, Presence::Unknown, false));
  alarm.lastDate = next.date;
  assert(nextOccurrence(config, next.start + 5, UTC).date == 20261116);
  alarm.lastDate = 0; alarm.skipDate = 20261109;
  assert(nextOccurrence(config, next.start + 5, UTC).date == 20261116);
  alarm.skipDate = 0;
  assert(!nextOccurrence(config, next.wake + LATE_START_SECONDS + 1, UTC, true));
  alarm.weekdays = 0; alarm.date = 20261109;
  assert(nextOccurrence(config, next.start, UTC).date == 20261109);
  assert(!nextOccurrence(config, next.wake + 301, UTC));
  config.enabled = false;
  assert(!nextOccurrence(config, next.start, UTC));

  config = example(); config.count = 2; config.alarms[1] = config.alarms[0];
  strcpy(config.alarms[0].id, "z"); strcpy(config.alarms[1].id, "a");
  assert(nextOccurrence(config, dateEpoch(20261109), UTC).index == 1);
}

void daylightSaving() {
  const uint32_t missing = dateEpoch(20260329) + 2 * 3600 + 30 * 60;
  assert(euLocal(resolveLocal(missing, EU)) == missing + 3600);
  const uint32_t repeated = dateEpoch(20261025) + 2 * 3600 + 30 * 60;
  assert(resolveLocal(repeated, EU) == dateEpoch(20261025) + 30 * 60);
  Config config = example();
  config.alarms[0].weekdays = 64; config.alarms[0].wakeMinute = 150;
  const uint32_t first = resolveLocal(repeated, EU);
  Occurrence due = nextOccurrence(config, first, EU, true);
  assert(due.date == 20261025);
  config.alarms[0].lastDate = due.date;
  assert(!nextOccurrence(config, first + 3600, EU, true));
}

void running() {
  Runner runner;
  Alarm alarm;
  runner.start(alarm, 1000);
  assert(runner.frame(1000).brightness == 0);
  uint8_t previous = 0;
  for (uint32_t elapsed = 0; elapsed <= 1800000; elapsed += 1000) {
    Frame frame = runner.frame(1000 + elapsed);
    assert(frame.brightness >= previous && frame.brightness <= alarm.brightness);
    previous = frame.brightness;
  }
  assert(runner.frame(1801000).phase == Phase::Holding);
  assert(runner.frame(3601000).phase == Phase::Fading);
  assert(runner.frame(3901000).phase == Phase::Finished);
  assert(!runner.active());
  runner.start(alarm, UINT32_MAX - 500);
  assert(runner.frame(500).phase == Phase::Rising);
  runner.start(alarm, 0, 1800000);
  assert(runner.frame(0).phase == Phase::Holding);
  assert(runner.snooze(1000));
  assert(runner.frame(2000).phase == Phase::Snoozed);
  assert(runner.frame(601000).phase == Phase::Rising);
  assert(runner.frame(661000).phase == Phase::Holding);
  runner.fadeOut(662000, runner.frame(662000));
  assert(runner.frame(665000).phase == Phase::Finished);
  runner.start(alarm, 0, 0, true);
  assert(!runner.snooze(0));
  assert(runner.frame(20000).brightness == alarm.brightness);
  assert(runner.frame(30000).phase == Phase::Finished);
  alarm.rampMinutes = 0;
  runner.start(alarm, 0);
  assert(runner.frame(0).brightness == alarm.brightness);
}

void presence() {
  PresenceTracker tracker;
  assert(tracker.state(0) == Presence::Unknown);
  tracker.observe(Presence::Present, 0);
  tracker.observe(Presence::Absent, 30000);
  assert(tracker.state(30000) == Presence::Present);
  tracker.observe(Presence::Absent, 60000);
  tracker.observe(Presence::Absent, 90000);
  assert(tracker.state(90000) == Presence::Present);
  assert(tracker.grace(90000));
  assert(tracker.confirmationAge(90000) == 90000);
  assert(tracker.remaining(90000) == PresenceTracker::MAX_AGE_MS - 90000);
  tracker.observe(Presence::Unknown, 120000);
  assert(tracker.state(300001) == Presence::Present);
  assert(tracker.state(PresenceTracker::MAX_AGE_MS) == Presence::Unknown);
  assert(tracker.remaining(PresenceTracker::MAX_AGE_MS) == 0);
  tracker.observe(Presence::Absent, PresenceTracker::MAX_AGE_MS);
  assert(tracker.state(PresenceTracker::MAX_AGE_MS) == Presence::Absent);
  assert(tracker.state(PresenceTracker::MAX_AGE_MS + PresenceTracker::OBSERVATION_AGE_MS) == Presence::Unknown);
  tracker.observe(Presence::Present, UINT32_MAX - 1000);
  assert(tracker.state(500) == Presence::Present);
  assert(tracker.state(180000) == Presence::Present);
  assert(tracker.state(PresenceTracker::MAX_AGE_MS) == Presence::Unknown);
  tracker.reset();
  assert(tracker.confirmationAge(2) == UINT32_MAX);
  for (uint32_t now = 0; now < PresenceTracker::MAX_AGE_MS; now += 30000) tracker.observe(Presence::Unknown, now);
  assert(tracker.state(PresenceTracker::MAX_AGE_MS) == Presence::Unknown); // Polls never create a lease.
  tracker.observe(Presence::Present, 1000);
  tracker.expire(1000 + PresenceTracker::MAX_AGE_MS);
  assert(tracker.state(1000) == Presence::Unknown); // Long pause followed by a full millis() rollover.
  assert(tracker.remaining(1000) == 0);
  tracker.observe(Presence::Present, 1000);
  assert(tracker.state(1001) == Presence::Present);
}

void monitoring() {
  const uint32_t now = dateEpoch(20261108);
  Occurrence next;
  next.start = now + 12 * 3600 + 1; next.wake = next.start + 1800;
  assert(presencePolicy(true, true, next, false, now).intervalMs == 0);
  next.start = now + 12 * 3600;
  assert(presencePolicy(true, true, next, false, now).intervalMs == 900000);
  next.start = now + 1801;
  assert(presencePolicy(true, true, next, false, now).mode == Monitoring::Scheduled);
  next.start = now + 1800;
  assert(presencePolicy(true, true, next, false, now).intervalMs == 300000);
  assert(presencePolicy(true, false, next, true, now).intervalMs == 600000);
  assert(presencePolicy(false, true, next, true, now).intervalMs == 0);
  assert(presencePolicy(true, false, next, false, now).intervalMs == 0);
  PresenceTiming timing;
  assert(timing.until(0, 0, false) == UINT32_MAX);
  assert(timing.until(0, 0, true) == 0);
  timing.completed(1000);
  assert(timing.until(1001, 900000, false) == 899999);
  assert(timing.until(1001, 0, true) == 4999);
  assert(timing.until(301000, 300000, false) == 0);
  assert(timing.until(301000, 900000, false) > 0);
  timing.completed(UINT32_MAX - 1000);
  assert(timing.until(500, 300000, false) == 298499);
}

void burst() {
  PresenceBurst round;
  assert(round.attempts() == 1);
  assert(!round.due(4999));
  assert(round.due(5000)); round.advanced(5000);
  assert(!round.due(11999));
  assert(round.due(12000)); round.advanced(12000);
  assert(!round.due(21999));
  assert(round.due(22000)); round.advanced(22000);
  assert(!round.fallbackDue(27000));
  for (uint32_t offset : {30000U, 40000U, 50000U, 60000U}) {
    assert(!round.due(offset - 1));
    assert(round.due(offset));
    round.advanced(offset);
    assert(!round.fallbackDue(offset));
  }
  assert(round.attempts() == 8);
  assert(!round.due(70000));
  assert(!round.fallbackDue(64999));
  assert(round.fallbackDue(65000));
  round.reset();
  assert(round.due(10000)); round.advanced(10000);
  assert(!round.due(12000)); // A delayed loop does not send missed retries back-to-back.
  assert(round.due(15000));
  assert(PresenceBurst::TIMEOUT_MS == 75000);
  assert(PresenceBurst::RECEIVE_WINDOW_MS > PresenceBurst::TIMEOUT_MS);
}

void logRing() {
  LogRing<unsigned, 96> log;
  assert(log.size() == 0 && !log.newest(0));
  for (unsigned i = 0; i < 200; ++i) log.append(i);
  assert(log.size() == 96 && log.generation() == 200);
  assert(*log.newest(0) == 199 && *log.newest(95) == 104);
  assert(!log.newest(96));
  unsigned read = 0;
  for (unsigned offset = 0; offset < log.size(); offset += 24) {
    for (unsigned page = 0; page < 24 && offset + page < log.size(); ++page) {
      assert(*log.newest(offset + page) == 199 - read++);
    }
  }
  assert(read == 96);
}

void packets() {
  const uint32_t target = 0xC0A8B22B, local = 0xC0A8B220;
  const uint16_t token = 123, port = 49999;
  uint8_t question[64];
  const size_t questionSize = Probe::mdnsQuestion(question, sizeof(question), target, token);
  assert(questionSize > 12 && questionSize < sizeof(question));
  assert(!Probe::mdnsQuestion(question, 12, target, token));
  size_t nameOffset = 12;
  char name[128];
  assert(Probe::dnsName(question, questionSize, nameOffset, name, sizeof(name)));
  assert(!strcmp(name, "43.178.168.192.in-addr.arpa"));
  uint8_t reply[128] = {0};
  memcpy(reply, question, questionSize);
  reply[2] = 0x80;
  Probe::write16(reply + 6, 1);
  size_t size = questionSize;
  reply[size++] = 0xC0; reply[size++] = 12;
  Probe::write16(reply + size, 12); size += 2;
  Probe::write16(reply + size, 1); size += 2;
  reply[size++] = 0; reply[size++] = 0; reply[size++] = 0; reply[size++] = 120;
  Probe::write16(reply + size, 3); size += 2;
  reply[size++] = 1; reply[size++] = 'x'; reply[size++] = 0;
  assert(Probe::mdnsReply(reply, size, target, token));
  assert(!Probe::mdnsReply(reply, size, target, token + 1));
  assert(!Probe::mdnsReply(reply, size, target + 1, token));
  for (size_t truncated = 0; truncated < size; ++truncated) assert(!Probe::mdnsReply(reply, truncated, target, token));
  uint8_t cycle[14] = {0}; cycle[12] = 0xC0; cycle[13] = 12;
  nameOffset = 12;
  assert(!Probe::dnsName(cycle, sizeof(cycle), nameOffset, name, sizeof(name)));
  const uint8_t ownMac[6] = {2, 3, 4, 5, 6, 7}, phoneMac[6] = {8, 9, 10, 11, 12, 13};
  uint8_t arp[42] = {0};
  memcpy(arp, ownMac, 6); memcpy(arp + 6, phoneMac, 6); memcpy(arp + 22, phoneMac, 6); memcpy(arp + 32, ownMac, 6);
  Probe::write16(arp + 12, 0x0806); Probe::write16(arp + 14, 1); Probe::write16(arp + 16, 0x0800);
  arp[18] = 6; arp[19] = 4; Probe::write16(arp + 20, 2);
  for (unsigned i = 0; i < 4; ++i) { arp[28 + i] = target >> ((3 - i) * 8); arp[38 + i] = local >> ((3 - i) * 8); }
  assert(Probe::arpReply(arp, sizeof(arp), target, local, ownMac));
  assert(!Probe::arpReply(arp, sizeof(arp), target + 1, local, ownMac));
  arp[21] = 1; assert(!Probe::arpReply(arp, sizeof(arp), target, local, ownMac)); arp[21] = 2;
  for (size_t truncated = 0; truncated < sizeof(arp); ++truncated) assert(!Probe::arpReply(arp, truncated, target, local, ownMac));
  uint8_t icmp[80] = {0};
  icmp[0] = 0x45; icmp[9] = 1; icmp[20] = 3; icmp[21] = 3; icmp[28] = 0x45; icmp[37] = 17;
  for (unsigned i = 0; i < 4; ++i) {
    icmp[12 + i] = icmp[44 + i] = target >> ((3 - i) * 8);
    icmp[16 + i] = icmp[40 + i] = local >> ((3 - i) * 8);
  }
  Probe::write16(icmp + 48, port); Probe::write16(icmp + 50, 5353); Probe::write16(icmp + 52, 12); Probe::write16(icmp + 56, token);
  assert(Probe::portUnreachable(icmp, 58, target, local, port, token));
  assert(!Probe::portUnreachable(icmp, 58, target, local, port + 1, token));
  assert(!Probe::portUnreachable(icmp, 58, target, local, port, token + 1));
  assert(!Probe::portUnreachable(icmp, 58, target + 1, local, port, token));
  for (size_t truncated = 0; truncated < 56; ++truncated) assert(!Probe::portUnreachable(icmp, truncated, target, local, port, token));
  uint32_t random = 5;
  uint8_t data[512];
  for (unsigned sample = 0; sample < 10000; ++sample) {
    for (uint8_t& value : data) { random = random * 1664525U + 1013904223U; value = random >> 24; }
    const size_t length = random % sizeof(data);
    Probe::mdnsReply(data, length, target, token);
    Probe::arpReply(data, length, target, local, ownMac);
    Probe::portUnreachable(data, length, target, local, port, token);
  }
}

void atomics() {
  Atomic<uint8_t> bits {0};
  assert(bits.fetch_or(1) == 0);
  assert(bits.fetch_or(4) == 1);
  assert(bits.load() == 5);
  assert(bits.exchange(0) == 5);
  assert(bits++ == 0);
  assert(--bits == 0);
  Atomic<bool> flag {true};
  assert(flag.exchange(false));
  assert(!flag.load());
  Atomic<uint32_t> revision {1};
  revision = UINT32_MAX;
  assert(revision.load() == UINT32_MAX);
}

void configuration() {
  Config config = example(), parsed;
  strcpy(config.presenceHost, "192.168.178.42");
  strcpy(config.alarms[0].label, "Frühstück 🌅");
  DynamicJsonDocument document(16384);
  serializeConfig(document.to<JsonObject>(), config);
  const char* error = "";
  assert(parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
  assert(!strcmp(parsed.alarms[0].label, config.alarms[0].label));
  document["alarms"][0]["wakeH"] = 24;
  assert(!parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
  document["alarms"][0]["wakeH"] = 7;
  document["alarms"][0]["brightness"] = -1;
  assert(!parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
  document["alarms"][0]["brightness"] = 180;
  document["alarms"][0]["dow"] = 0;
  assert(!parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
  document["alarms"][0]["date"] = 20261109;
  assert(parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
  document["alarms"].as<JsonArray>().add(document["alarms"][0]);
  assert(!parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
  assert(validLabel("<script>alert('x')</script>")); // The UI must render it as text, not HTML.
  assert(!validLabel(std::string(33, 'x').c_str()));
  assert(!validLabel("\xC0\x80"));
  assert(!validLabel("\xF0\x80\x80\x80"));
  assert(!validId("x' onclick='bad"));
  uint32_t random = 17;
  for (unsigned sample = 0; sample < 10000; ++sample) {
    char label[129];
    for (unsigned i = 0; i < 128; ++i) {
      random = random * 1664525U + 1013904223U;
      label[i] = char(random >> 24);
    }
    label[128] = 0;
    validLabel(label); // Sanitizer coverage for truncated/invalid UTF-8 at every boundary.
  }
  assert(!validHost("http://192.168.178.42"));
  assert(!validHost(std::string(64, 'x').c_str()));
  assert(validHost("phone.example"));
  document.clear();
  assert(!deserializeJson(document, "[{\"id\":\"legacy\",\"enabled\":true,\"wakeH\":7,\"wakeM\":0,\"offsetMin\":90,\"dow\":31,\"preset\":7,\"label\":\"Old\"}]"));
  assert(parseConfig(document.as<JsonVariantConst>(), parsed, true, error));
  assert(parsed.alarms[0].scene == Scene::Preset && parsed.alarms[0].rampMinutes == 90);
  config = example(); config.count = MAX_ALARMS;
  for (unsigned i = 0; i < MAX_ALARMS; ++i) {
    snprintf(config.alarms[i].id, sizeof(config.alarms[i].id), "alarm-%u", i);
    std::string label(1, char('A' + i));
    for (unsigned j = 0; j < 31; ++j) label += "😀";
    strcpy(config.alarms[i].label, label.c_str());
  }
  document.clear();
  serializeConfig(document.to<JsonObject>(), config);
  std::string json;
  serializeJson(document, json);
  assert(json.size() <= 10000);
  // Native pointers make JSON slots larger than on the 32-bit ESP targets.
  DynamicJsonDocument constrained(JSON_OBJECT_SIZE(18) * MAX_ALARMS + JSON_ARRAY_SIZE(MAX_ALARMS) + JSON_OBJECT_SIZE(6) + 3000);
  assert(!deserializeJson(constrained, json));
  assert(parseConfig(constrained.as<JsonVariantConst>(), parsed, false, error));
  config.count = MAX_ALARMS;
  document["alarms"].as<JsonArray>().add(document["alarms"][0]);
  assert(!parseConfig(document.as<JsonVariantConst>(), parsed, false, error));
}
